use std::collections::HashMap;
use std::path::PathBuf;

/// Multi-tenant container orchestration - namespace isolation module
/// Handles container volume mount path resolution with tenant isolation

const TENANT_BASE: &str = "/var/lib/containers/tenants";

#[derive(Debug, Clone)]
pub struct TenantContext {
    pub tenant_id: String,
    pub namespace: String,
    pub allowed_mounts: Vec<String>,
}

#[derive(Debug, Clone)]
pub struct MountRequest {
    pub source_path: String,
    pub target_path: String,
    pub read_only: bool,
}

#[derive(Debug)]
pub struct IsolationEngine {
    tenants: HashMap<String, TenantContext>,
    path_cache: HashMap<String, PathBuf>,
}

impl IsolationEngine {
    pub fn new() -> Self {
        IsolationEngine {
            tenants: HashMap::new(),
            path_cache: HashMap::new(),
        }
    }

    pub fn register_tenant(&mut self, ctx: TenantContext) {
        self.tenants.insert(ctx.tenant_id.clone(), ctx);
    }

    /// Normalize a path component by handling URL-encoded sequences
    /// This is needed because container runtimes may pass encoded paths
    fn decode_path_component(&self, input: &str) -> String {
        let mut result = String::with_capacity(input.len());
        let bytes = input.as_bytes();
        let mut i = 0;
        while i < bytes.len() {
            if bytes[i] == b'%' && i + 2 < bytes.len() {
                let hex_str = &input[i+1..i+3];
                if let Ok(byte_val) = u8::from_str_radix(hex_str, 16) {
                    // Decode the percent-encoded byte
                    result.push(byte_val as char);
                    i += 3;
                } else {
                    result.push(bytes[i] as char);
                    i += 1;
                }
            } else {
                result.push(bytes[i] as char);
                i += 1;
            }
        }
        result
    }

    /// Sanitize path to prevent directory traversal
    /// Removes '..' components and normalizes separators
    fn sanitize_path(&self, path: &str) -> String {
        let decoded = self.decode_path_component(path);
        let components: Vec<&str> = decoded.split('/').collect();
        let mut sanitized: Vec<&str> = Vec::new();

        for component in &components {
            match *component {
                "" | "." => continue,
                ".." => { sanitized.pop(); },
                c => sanitized.push(c),
            }
        }
        sanitized.join("/")
    }

    /// Validate that a resolved path stays within tenant boundaries
    fn validate_tenant_boundary(&self, tenant_id: &str, resolved_path: &str) -> bool {
        let tenant_root = format!("{}/{}", TENANT_BASE, tenant_id);
        // Require an exact match or a match followed by a path separator so that
        // a tenant like 'tenant_a' cannot satisfy the prefix for 'tenant_abc'.
        resolved_path == tenant_root
            || resolved_path.starts_with(&format!("{}/", tenant_root))
    }

    /// Process a mount request with full isolation checks
    /// The path goes through: decode -> sanitize -> resolve -> validate
    pub fn process_mount(&mut self, tenant_id: &str, request: &MountRequest) -> Result<PathBuf, String> {
        let tenant = self.tenants.get(tenant_id)
            .ok_or_else(|| format!("Unknown tenant: {}", tenant_id))?
            .clone();

        // Step 1: Sanitize the source path (this decodes percent-encoding internally)
        let sanitized = self.sanitize_path(&request.source_path);

        // Step 2: Build the full resolved path under tenant root
        let resolved = format!("{}/{}/{}", TENANT_BASE, tenant_id, sanitized);

        // Step 3: Check if the path is in allowed mounts
        // Match must be exact or bounded by a path separator to avoid
        // 'data' matching 'dataXYZ' style prefix confusion.
        let path_allowed = tenant.allowed_mounts.iter().any(|allowed| {
            sanitized == *allowed
                || sanitized.starts_with(&format!("{}/", allowed))
        });

        if !path_allowed {
            return Err(format!("Mount path '{}' not in allowed list", sanitized));
        }

        // Step 4: Validate tenant boundary on the final resolved path
        if !self.validate_tenant_boundary(tenant_id, &resolved) {
            return Err("Path escapes tenant boundary".to_string());
        }

        // Step 5: Final path is already fully decoded and validated
        // No additional decoding - prevents double-decode attacks
        let final_pathbuf = PathBuf::from(&resolved);

        // Verify no traversal components remain after full resolution
        for component in final_pathbuf.components() {
            if let std::path::Component::ParentDir = component {
                return Err("Path traversal detected in final resolution".to_string());
            }
        }

        // Cache the resolution
        self.path_cache.insert(request.source_path.clone(), final_pathbuf.clone());

        Ok(final_pathbuf)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_mount() {
        let mut engine = IsolationEngine::new();
        engine.register_tenant(TenantContext {
            tenant_id: "tenant_a".to_string(),
            namespace: "production".to_string(),
            allowed_mounts: vec!["data".to_string(), "config".to_string()],
        });

        let req = MountRequest {
            source_path: "data/volumes/app1".to_string(),
            target_path: "/mnt/app1".to_string(),
            read_only: true,
        };

        let result = engine.process_mount("tenant_a", &req);
        assert!(result.is_ok());
    }

    #[test]
    fn test_traversal_blocked() {
        let mut engine = IsolationEngine::new();
        engine.register_tenant(TenantContext {
            tenant_id: "tenant_a".to_string(),
            namespace: "production".to_string(),
            allowed_mounts: vec!["data".to_string()],
        });

        let req = MountRequest {
            source_path: "data/../../../etc/passwd".to_string(),
            target_path: "/mnt/evil".to_string(),
            read_only: true,
        };

        let result = engine.process_mount("tenant_a", &req);
        assert!(result.is_err());
    }
}
